<?php
$fm = "/opt/psa/admin/bin/filemng";
$user = "bmcars.bahman.ir_vzb4o368qoo";
$httpdocs = "/var/www/vhosts/bahman.ir/httpdocs";

// 1) Patch .htaccess rewrite
$ht = $httpdocs . "/.htaccess";
$c = file_get_contents($ht);
if (strpos($c, "product-compare-data") === false) {
  $needle = "RewriteRule ^product-menu-data/?$ index.php?include=product_menu_json [L,QSA]";
  $add = $needle . "\n    RewriteRule ^product-compare-data/?$ index.php?include=product_compare_json [L,QSA]";
  if (strpos($c, $needle) === false) {
    echo "HTACCESS_NEEDLE_MISS\n";
  } else {
    $c2 = str_replace($needle, $add, $c);
    $tmp = "/tmp/_htaccess_compare";
    file_put_contents($tmp, $c2);
    echo "htaccess_bytes=" . filesize($tmp) . "\n";
    echo trim((string)shell_exec($fm . " " . escapeshellarg($user) . " cp " . escapeshellarg($tmp) . " " . escapeshellarg($ht) . " 2>&1")) . "\n";
    @unlink($tmp);
    echo "htaccess_has_rule=" . (strpos(file_get_contents($ht), "product-compare-data") !== false ? "1" : "0") . "\n";
  }
} else {
  echo "htaccess_already=1\n";
}

// 2) Deploy compare frontend files
$payload = [
  'templates/bahman/assets/product-compare.js' => '',
  'templates/bahman/assets/product-compare.css' => '',
  'templates/bahman/show_product.tpl' => '',
  'templates/bahman/includes/header_include.tpl' => '',
  'templates/bahman/includes/footer_include.tpl' => '',
];
foreach ($payload as $rel => $b64) {
  $dest = $httpdocs . "/" . $rel;
  $tmp = "/tmp/_cmp_" . str_replace("/", "_", $rel);
  file_put_contents($tmp, base64_decode($b64));
  echo "bytes_$rel=" . filesize($tmp) . "\n";
  echo trim((string)shell_exec($fm . " " . escapeshellarg($user) . " cp " . escapeshellarg($tmp) . " " . escapeshellarg($dest) . " 2>&1")) . "\n";
  @unlink($tmp);
  echo "exists_$rel=" . (is_file($dest) ? "1" : "0") . "\n";
}

// clear smarty compile for product templates
$clear = $fm . ' root exec / bash -c ' . escapeshellarg(
  "rm -f /var/www/vhosts/bahman.ir/httpdocs/templates_c/*show_product* /var/www/vhosts/bahman.ir/httpdocs/templates_c/*footer* /tmp/bahman_*.html 2>/dev/null; "
  ."curl -s -o /tmp/cmp_api.json -w '%{http_code}' -H 'Accept: application/json' 'http://127.0.0.1/product-compare-data?ids=590,588' -H 'Host: bahman.ir'; "
  ."echo; head -c 180 /tmp/cmp_api.json; echo"
) . ' --allow-root 2>&1';
echo trim((string)shell_exec($clear)) . "\n";
echo "DONE\n";
